import{_ as r,o as a,c as l,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"الإسكان وحماية البيئة","description":"","frontmatter":{},"headers":[],"relativePath":"ar/39-住房与环境保障.md","filePath":"ar/39-住房与环境保障.md"}'),i={name:"ar/39-住房与环境保障.md"};function n(e,t,d,s,h,g){return a(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="الإسكان-وحماية-البيئة" tabindex="-1">الإسكان وحماية البيئة <a class="header-anchor" href="#الإسكان-وحماية-البيئة" aria-label="Permalink to &quot;الإسكان وحماية البيئة&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>39</td></tr><tr><td>الوحدة</td><td>أنماط الحضارة والأنظمة الاجتماعية</td></tr><tr><td>الكلمات المفتاحية</td><td>ضمان الإسكان، حماية البيئة، التكافل البيئي، الفضاءات الصالحة للسكن، التنمية المستدامة</td></tr></tbody></table><h2 id="أولاً-المفاهيم-الجوهرية-للإسكان-وحماية-البيئة" tabindex="-1">أولاً: المفاهيم الجوهرية للإسكان وحماية البيئة <a class="header-anchor" href="#أولاً-المفاهيم-الجوهرية-للإسكان-وحماية-البيئة" aria-label="Permalink to &quot;أولاً: المفاهيم الجوهرية للإسكان وحماية البيئة&quot;">​</a></h2><p>«لكل ساكن مسكن» قضية معيشية أساسية يجب أن تواجهها كل حضارة. في عصر نظام الزراعة الافتراسية، كان المسكن والأرض محتكرين من قِلة من الأقوياء والطوائف، وكانت جماهير القاع في الغالب بلا مأوى ثابت، مضطرين للزراعة والعيش في بيئات قاسية. والأخطر أن الزراعة الافتراسية سببت دماراً هائلاً للبيئة — عروق الروح نُهبت بفرط، والبيئة تلوثت بشدة، وموارد الكواكب استُنزفت استنزافاً افتراسياً، مما حوّل كثيراً من الكواكب التي كانت صالحة للسكن إلى أرض قاحلة.</p><p>بعد تأسيس حضارة التكافل المرساة، أصبح ضمان الإسكان وحماية البيئة من المحتويات الجوهرية لبناء المؤسسات الاجتماعية. يمكن تلخيص المفهوم الجوهري للإسكان وحماية البيئة في ستة عشر حرفاً: «مسكن لكل ساكن، تكافل بيئي، تنمية مستدامة، صلاحية للسكن لعشرة آلاف عرق».</p><p>تشمل الأهداف الجوهرية للإسكان وحماية البيئة:</p><ol><li><strong>ضمان الحق الأساسي في السكن</strong>: ضمان حصول كل كائن تكافلي على مسكن لائق وآمن وملائم، وعدم تأثير مشاكل الإسكان على البقاء والتطور</li><li><strong>حماية البيئة الإيكولوجية</strong>: إقامة نظام متكامل لحماية البيئة، والحفاظ على التوازن البيئي، ومنع الأنشطة الزراعية من الإضرار بالبيئة</li><li><strong>بناء فضاءات صالحة للسكن</strong>: عبر التخطيط العلمي والوسائل التقنية، بناء فضاءات صالحة للسكن والزراعة</li><li><strong>تحقيق التنمية المستدامة</strong>: مع تلبية احتياجات الجيل الحالي، عدم الإضرار بقدرة الأجيال القادمة على تلبية احتياجاتها، وتحقيق الاستخدام المستدام للموارد والبيئة</li><li><strong>تعزيز صلاحية السكن لعشرة آلاف عرق</strong>: مراعاة بناء الإسكان والبيئة الكاملة للخصائص الفسيولوجية وعادات المعيشة للأعراق المختلفة، وضمان صلاحية السكن للجميع</li></ol><h2 id="ثانياً-نظام-ضمان-الإسكان" tabindex="-1">ثانياً: نظام ضمان الإسكان <a class="header-anchor" href="#ثانياً-نظام-ضمان-الإسكان" aria-label="Permalink to &quot;ثانياً: نظام ضمان الإسكان&quot;">​</a></h2><p>يتبع نظام ضمان الإسكان في الحضارة التكافلية مبادئ «ضمان الأساس، دفع التحسين، تعدد القنوات، الاستدامة»، مبيناً نظاماً متعدد المستويات لتوفير المساكن:</p><h3 id="_2-1-المستويات-الثلاثة-لتوفير-المساكن" tabindex="-1">2.1 المستويات الثلاثة لتوفير المساكن <a class="header-anchor" href="#_2-1-المستويات-الثلاثة-لتوفير-المساكن" aria-label="Permalink to &quot;2.1 المستويات الثلاثة لتوفير المساكن&quot;">​</a></h3><table tabindex="0"><thead><tr><th>المستوى</th><th>الاسم</th><th>الفئة المستهدفة</th><th>نوع المسكن</th><th>الإيجار/السعر</th></tr></thead><tbody><tr><td>المستوى الأول</td><td>المساكن المضمونة</td><td>الفئات منخفضة الدخل، المزارعون الجدد</td><td>شقق زراعية أساسية، مهاجع جماعية</td><td>مجاناً أو بإيجار منخفض للغاية</td></tr><tr><td>المستوى الثاني</td><td>المساكن المحسّنة</td><td>الفئات متوسطة الدخل، المزارعون المتوسطون</td><td>مساكن زراعية قياسية، شقق عائلية</td><td>بسعر التكلفة أو إيجار منخفض</td></tr><tr><td>المستوى الثالث</td><td>المساكن التجارية</td><td>الفئات مرتفعة الدخل، المزارعون المتقدمون</td><td>مساكن زراعية راقية، قصور كهفية مستقلة</td><td>بسعر السوق</td></tr></tbody></table><h3 id="_2-2-نظام-المساكن-المضمونة" tabindex="-1">2.2 نظام المساكن المضمونة <a class="header-anchor" href="#_2-2-نظام-المساكن-المضمونة" aria-label="Permalink to &quot;2.2 نظام المساكن المضمونة&quot;">​</a></h3><p>المساكن المضمونة هي قلب نظام ضمان الإسكان، وتضمن الحق الأساسي في السكن لكل كائن تكافلي:</p><ul><li><strong>الشقق الزراعية الأساسية</strong>: شقق صغيرة للمزارعين الجدد والأفراد العزاب، مجهزة بمرافق زراعية أساسية، بإيجار منخفض للغاية أو مجاناً</li><li><strong>المهاجع الجماعية</strong>: إقامة جماعية لتلاميذ الطوائف والطلاب والعاملين الجماعيين، مع فضاءات زراعية مشتركة</li><li><strong>المساكن المضمونة العائلية</strong>: مساكن متكاملة للأسر منخفضة الدخل، بمساحة مناسبة وتجهيزات كاملة</li><li><strong>المساكن المضمونة الخاصة</strong>: مساكن ملائمة للأحياء ذوي الإعاقة والأعراق الخاصة والمزارعين المسنين وغيرهم من الفئات الخاصة</li></ul><p>يتبع طلب وتوزيع المساكن المضمونة مبادئ «الشفافية والإنصاف والعدالة»، وتتم الطلبات والمراجعات عبر الشبكة التكافلية، وتكون نتائج التوزيع علنية وشفافة.</p><h3 id="_2-3-نظام-المساكن-المحسّنة" tabindex="-1">2.3 نظام المساكن المحسّنة <a class="header-anchor" href="#_2-3-نظام-المساكن-المحسّنة" aria-label="Permalink to &quot;2.3 نظام المساكن المحسّنة&quot;">​</a></h3><p>تستهدف المساكن المحسّنة الفئات متوسطة الدخل ذات القدرة الاقتصادية، وتقدم بسعر التكلفة أو إيجار منخفض:</p><ul><li><strong>المساكن الزراعية القياسية</strong>: مساكن متكاملة بغرفة زراعة مستقلة، مناسبة للأفراد والأسر ذات أساس زراعي معين</li><li><strong>الشقق العائلية</strong>: شقق متوسطة الحجم مناسبة للأسر، مع فضاءات أنشطة للأطفال ومناطق زراعة عائلية</li><li><strong>شقق الكفاءات</strong>: مساكن تفضيلية للكفاءات الرفيعة المستقدمة والكوادر التقنية المتخصصة</li></ul><p>يتعدل توفير المساكن المحسّنة ديناميكياً حسب الطلب، لضمان حصول الفئات متوسطة الدخل على مساكن ملائمة بتكاليف معقولة.</p><h3 id="_2-4-نظام-المساكن-التجارية" tabindex="-1">2.4 نظام المساكن التجارية <a class="header-anchor" href="#_2-4-نظام-المساكن-التجارية" aria-label="Permalink to &quot;2.4 نظام المساكن التجارية&quot;">​</a></h3><p>تستهدف المساكن التجارية الفئات مرتفعة الدخل وتقدم بأسعار السوق:</p><ul><li><strong>المساكن الزراعية الراقية</strong>: مساكن فاخرة مجهزة بمرافق زراعية متقدمة</li><li><strong>القصور الكهفية المستقلة</strong>: قصور كهفية زراعية بفضاء مستقل وإمداد طاقي</li><li><strong>المساكن المخصصة</strong>: مساكن خاصة مصممة حسب احتياجات الفرد</li></ul><p>تتبع معاملات المساكن التجارية قواعد السوق، لكن الحكومة تنظم عبر الضرائب العقارية وإدارة الأراضي وغيرها من الوسائل، لمنع الارتفاع المفرط للأسعار والمضاربة العقارية.</p><h3 id="_2-5-تجهيزات-فضاءات-الزراعة" tabindex="-1">2.5 تجهيزات فضاءات الزراعة <a class="header-anchor" href="#_2-5-تجهيزات-فضاءات-الزراعة" aria-label="Permalink to &quot;2.5 تجهيزات فضاءات الزراعة&quot;">​</a></h3><p>في الحضارة التكافلية، المسكن ليس مجرد فضاء معيشة، بل فضاء زراعة أيضاً. كل مسكن مجهز بمرافق زراعية متناسبة مع احتياجات ساكنيه:</p><ul><li><strong>منطقة الزراعة الأساسية</strong>: لكل مسكن منطقة زراعة أساسية مزودة بمنافذ توصيل طاقة أساسية</li><li><strong>إمداد الطاقة</strong>: إمداد طاقي مستقر للمساكن عبر شبكة المرساة، لتلبية احتياجات الزراعة</li><li><strong>العزل الصوتي والطاقي</strong>: مناطق الزراعة مزودة بمرافق عزل صوتي وحماية طاقية، لمنع إزعاج الآخرين بالزراعة</li><li><strong>الفضاءات الزراعية العامة</strong>: توفر المجتمعات فضاءات مشتركة كقاعات الزراعة العامة وغرف معدات الزراعة</li></ul><h2 id="ثالثاً-نظام-حماية-البيئة" tabindex="-1">ثالثاً: نظام حماية البيئة <a class="header-anchor" href="#ثالثاً-نظام-حماية-البيئة" aria-label="Permalink to &quot;ثالثاً: نظام حماية البيئة&quot;">​</a></h2><p>يتبع نظام حماية البيئة في الحضارة التكافلية مبادئ «الوقاية أولاً، المعالجة الشاملة، الاستعادة البيئية، الاستخدام المستدام»، مبيناً إطاراً شاملاً لحماية البيئة:</p><h3 id="_3-1-المعايير-البيئية-والرقابة" tabindex="-1">3.1 المعايير البيئية والرقابة <a class="header-anchor" href="#_3-1-المعايير-البيئية-والرقابة" aria-label="Permalink to &quot;3.1 المعايير البيئية والرقابة&quot;">​</a></h3><p>وضعت الحضارة التكافلية معايير بيئية صارمة، تضبط الأثر البيئي للأنشطة الزراعية والإنتاجية:</p><ul><li><strong>معايير الانبعاثات الطاقية</strong>: قيود صارمة على الانبعاثات الطاقية الناتجة عن الزراعة والإنتاج</li><li><strong>معايير استخراج الموارد</strong>: ضبط استخراج عروق الروح والمعادن والموارد البيولوجية وغيرها، ومنع الاستخراج المفرط</li><li><strong>الخطوط الحمراء لحماية البيئة</strong>: تحديد خطوط حمراء لحماية البيئة، ويُحظر أي نشاط تخريبي داخلها</li><li><strong>تقييم الأثر البيئي</strong>: المشاريع الزراعية والإنشائية الكبرى ملزمة بإجراء تقييم الأثر البيئي</li></ul><p>تتولى مؤسسات رقابية بيئية متخصصة الإشراف على حماية البيئة، فتراقب جودة البيئة في الزمن الحقيقي عبر الشبكة التكافلية وتفرض عقوبات صارمة على الأنشطة المخالفة.</p><h3 id="_3-2-تقنيات-معالجة-التلوث" tabindex="-1">3.2 تقنيات معالجة التلوث <a class="header-anchor" href="#_3-2-تقنيات-معالجة-التلوث" aria-label="Permalink to &quot;3.2 تقنيات معالجة التلوث&quot;">​</a></h3><p>طورت الحضارة التكافلية تقنيات متقدمة لمعالجة التلوث:</p><ul><li><strong>معالجة التلوث الطاقي</strong>: عبر ترشيح الطاقة وتحويل الطاقة وغيرها من التقنيات، معالجة التلوث الطاقي الناتج عن الأنشطة الزراعية</li><li><strong>معالجة التلوث المادي</strong>: عبر المعالجة الحيوية والمعالجة الكيميائية والتنقية الفيزيائية وغيرها من التقنيات، معالجة التلوث المادي</li><li><strong>معالجة تلوث القوانين</strong>: عبر فصل القوانين ومعادلة القوانين وغيرها من التقنيات، معالجة التلوث البيئي الناتج عن تآكل القوانين</li><li><strong>تقنيات الاستعادة البيئية</strong>: عبر نظام دورة الحياة وتقنيات الهندسة البيئية، استعادة النظم الإيكولوجية المتضررة</li></ul><h3 id="_3-3-الاستخدام-المستدام-للموارد" tabindex="-1">3.3 الاستخدام المستدام للموارد <a class="header-anchor" href="#_3-3-الاستخدام-المستدام-للموارد" aria-label="Permalink to &quot;3.3 الاستخدام المستدام للموارد&quot;">​</a></h3><p>تؤكد الحضارة التكافلية على الاستخدام المستدام للموارد وتعارض التنمية الافتراسية:</p><ul><li><strong>حصص استخراج الموارد</strong>: تطبيق نظام حصص على استخراج الموارد غير المتجددة، لضمان الاستخدام طويل الأمد</li><li><strong>إعادة تدوير الموارد</strong>: تطوير تقنيات إعادة تدوير الموارد بنشاط، ورفع كفاءة استخدامها</li><li><strong>تطوير الطاقة المتجددة</strong>: تطوير نشط للطاقة الشمسية والريحية والمائية وطاقة الحقول الطاقية</li><li><strong>أبحاث الموارد البديلة</strong>: تطوير بدائل للموارد النادرة، وتقليل الاعتماد عليها</li></ul><h3 id="_3-4-الحماية-والاستعادة-البيئيتان" tabindex="-1">3.4 الحماية والاستعادة البيئيتان <a class="header-anchor" href="#_3-4-الحماية-والاستعادة-البيئيتان" aria-label="Permalink to &quot;3.4 الحماية والاستعادة البيئيتان&quot;">​</a></h3><p>تولي الحضارة التكافلية أهمية كبرى للحماية والاستعادة البيئيتين:</p><ul><li><strong>المحميات الطبيعية</strong>: إنشاء محميات طبيعية على جميع المستويات، وحماية الأنواع النادرة والنظم الإيكولوجية البكر</li><li><strong>مشاريع الاستعادة البيئية</strong>: استعادة النظم الإيكولوجية المتضررة، وإعادة التوازن البيئي</li><li><strong>برامج حماية الأنواع</strong>: حماية الأنواع المهددة بالانقراض وتكاثرها، ومنع انقراضها</li><li><strong>آلية التعويض البيئي</strong>: تعويض المناطق والفئات المتضررة بسبب الحماية البيئية</li></ul><h2 id="رابعاً-بناء-الفضاءات-الصالحة-للسكن" tabindex="-1">رابعاً: بناء الفضاءات الصالحة للسكن <a class="header-anchor" href="#رابعاً-بناء-الفضاءات-الصالحة-للسكن" aria-label="Permalink to &quot;رابعاً: بناء الفضاءات الصالحة للسكن&quot;">​</a></h2><p>على أساس الإسكان وحماية البيئة، تدفع الحضارة التكافلية بنشاط بناء الفضاءات الصالحة للسكن:</p><h3 id="_4-1-التخطيط-الحضري" tabindex="-1">4.1 التخطيط الحضري <a class="header-anchor" href="#_4-1-التخطيط-الحضري" aria-label="Permalink to &quot;4.1 التخطيط الحضري&quot;">​</a></h3><p>يتبع التخطيط الحضري في الحضارة التكافلية مبادئ «المتراص والاخضرار والذكاء والإنسانية»:</p><ul><li><strong>التخطيط المتراص</strong>: اعتماد المدن تخطيطاً متراصاً، وتقليل احتلال الأراضي واستهلاك طاقة النقل</li><li><strong>الفضاءات الخضراء</strong>: إبقاء المدن على فضاءات خضراء وافرة كالأحزمة الخضراء والحدائق والأراضي الرطبة</li><li><strong>الإدارة الذكية</strong>: عبر شبكة المرساة والتقنيات الذكية، تحقيق الإدارة الذكية للمدن</li><li><strong>الرعاية الإنسانية</strong>: مراعاة التخطيط الحضري الكاملة لاحتياجات المجموعات المختلفة من الأعراق والأعمار والقدرات</li></ul><h3 id="_4-2-بناء-المجتمعات-الزراعية" tabindex="-1">4.2 بناء المجتمعات الزراعية <a class="header-anchor" href="#_4-2-بناء-المجتمعات-الزراعية" aria-label="Permalink to &quot;4.2 بناء المجتمعات الزراعية&quot;">​</a></h3><p>تبني الحضارة التكافلية بنشاط مجتمعات زراعية تجمع بين السكن والزراعة والخدمات:</p><ul><li><strong>مراكز الزراعة المجتمعية</strong>: لكل مجتمع مركز زراعة، يوفر فضاءات زراعة عامة وإرشاداً زراعياً</li><li><strong>مراكز الخدمات المجتمعية</strong>: توفير خدمات شاملة كالصحة والتعليم والتجارة والترفيه</li><li><strong>المساحات الخضراء المجتمعية</strong>: إبقاء المجتمعات على مساحات خضراء وترفيهية وافرة</li><li><strong>الثقافة المجتمعية</strong>: تنمية الثقافة المجتمعية، وتعزيز شعور الانتماء والتماسك لدى السكان</li></ul><h3 id="_4-3-الفضاءات-الصالحة-للسكن-عبر-الأبعاد" tabindex="-1">4.3 الفضاءات الصالحة للسكن عبر الأبعاد <a class="header-anchor" href="#_4-3-الفضاءات-الصالحة-للسكن-عبر-الأبعاد" aria-label="Permalink to &quot;4.3 الفضاءات الصالحة للسكن عبر الأبعاد&quot;">​</a></h3><p>مع تقدم استكشاف الأبعاد، بدأت الحضارة التكافلية بناء فضاءات صالحة للسكن في أبعاد أخرى:</p><ul><li><strong>تحويل صلاحية الأبعاد للسكن</strong>: تحويل الأبعاد الملائمة لتصبح صالحة للسكن، وبناء فضاءات سكنية وزراعية جديدة</li><li><strong>الهجرة البيئية</strong>: نقل السكان بشكل مخطط من الأبعاد ذات الموارد المتوترة إلى أبعاد صالحة للسكن حديثة التطوير</li><li><strong>الإسكان عبر الأبعاد</strong>: توفير ضمان إسكان عبر الأبعاد للمزارعين المسافرين بينها بكثرة</li></ul><h2 id="خامساً-اختلافات-نماذج-الإسكان-والبيئة-بين-الأنماط-الخمسة" tabindex="-1">خامساً: اختلافات نماذج الإسكان والبيئة بين الأنماط الخمسة <a class="header-anchor" href="#خامساً-اختلافات-نماذج-الإسكان-والبيئة-بين-الأنماط-الخمسة" aria-label="Permalink to &quot;خامساً: اختلافات نماذج الإسكان والبيئة بين الأنماط الخمسة&quot;">​</a></h2><p>لكل نمط من الأنماط الخمسة للحضارة التكافلية خصائصه في نماذج الإسكان والبيئة:</p><table tabindex="0"><thead><tr><th>النمط</th><th>خصائص نموذج الإسكان</th><th>خصائص النموذج البيئي</th></tr></thead><tbody><tr><td>النمط الآسيوي الشرقي المكثف</td><td>كثافة عالية، تركز، مهاجع جماعية أساساً</td><td>رقابة صارمة، حوكمة فعالة، استعادة سريعة</td></tr><tr><td>النمط الإسكندنافي الرفاهي</td><td>ضمان عالٍ، جودة عالية، شخصي</td><td>معايير عالية، استثمار عالٍ، بيئة أولاً</td></tr><tr><td>النمط الأمريكي الشمالي التعددي</td><td>تسويقي، متنوع، كثافة منخفضة</td><td>حوكمة سوقية، يقودها التقنية، حماية الموارد</td></tr><tr><td>النمط الأوروبي القاري الاجتماعي</td><td>سكن اجتماعي، سكن تعاوني، توزيع متوازن</td><td>مشاركة جمعيات، حوكمة تشاورية، تنمية مستدامة</td></tr><tr><td>النمط النامي اللاحق</td><td>الضمان أولاً، بناء سريع، تحسن تدريجي</td><td>التنمية والحماية معاً، معالجة مركّزة</td></tr></tbody></table><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>الإسكان وحماية البيئة هما «حجر زاوية المعيشة» و«الحاجز البيئي» لحضارة التكافل المرساة. عبر نظام ضمان الإسكان متعدد المستويات ونظام حماية البيئة الشامل والبناء العلمي للفضاءات الصالحة للسكن، حققت الحضارة التكافلية أهداف «مسكن لكل ساكن، تكافل بيئي، تنمية مستدامة، صلاحية للسكن لعشرة آلاف عرق». ضمان الإسكان يمكن كل كائن تكافلي من الزراعة باطمئنان، وحماية البيئة ترسي الأساس البيئي للتنمية طويلة الأمد للحضارة. وهما متكاملان، يسندان معاً تقدم عشرة آلاف عرق معاً والتنمية المستدامة للحضارة التكافلية.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>45-住房保障法 (قانون ضمان الإسكان)</li><li>46-环境保护法 (قانون حماية البيئة)</li><li>32-北欧福利型文明 (حضارة الرفاهية الشمالية الأوروبية)</li></ul>',59)])])}const b=r(i,[["render",n]]);export{p as __pageData,b as default};
